"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["21561"],{26562(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.formulario_processo.chamadas_sem_formulario_obrigatorio","status":422,"titulo":"A fase organizada em chamadas n\xe3o tem formul\xe1rio obrigat\xf3rio"},"descricao":{"codigo":"uniplus.selecao.formulario_processo.chamadas_sem_formulario_obrigatorio","requisitos":["UNI-REQ-0144","UNI-REQ-0552"],"oQueAconteceu":["Uma fase do cronograma \xe9 organizada em chamadas (como a habilita\xe7\xe3o, em que cada chamada convoca candidatos para enviar os seus documentos), mas nenhum formul\xe1rio obrigat\xf3rio est\xe1 ligado a ela. \xc9 o formul\xe1rio obrigat\xf3rio da fase que todo convocado preenche e envia em cada chamada, e sem ele a chamada n\xe3o teria o que receber. A mensagem aponta a fase pela chave dela na configura\xe7\xe3o.","Cada fase organizada em chamadas sem formul\xe1rio obrigat\xf3rio gera uma recusa pr\xf3pria, na ordem do cronograma. O rascunho pode ficar sem o formul\xe1rio enquanto a configura\xe7\xe3o \xe9 montada. A recusa acontece ao congelar uma vers\xe3o: publica\xe7\xe3o inicial ou retifica\xe7\xe3o em ato \xfanico; a confer\xeancia de conformidade do processo mostra a mesma falta. Nada \xe9 congelado."],"comoResolver":["Grave um formul\xe1rio obrigat\xf3rio (`obrigatorio` verdadeiro) ligado a cada fase indicada, com as se\xe7\xf5es e os itens que o convocado preenche, e repita a opera\xe7\xe3o. Em processo j\xe1 publicado, a cria\xe7\xe3o do formul\xe1rio \xe9 uma altera\xe7\xe3o da configura\xe7\xe3o e se faz numa retifica\xe7\xe3o."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Formulario processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);